INSERT INTO product_sections (product_id, section_id, primary_brick_id, build_strategy, thesis, composition_note, reuse_weight, evidence_rule) VALUES (2, 1, 'DC-WORKLOAD-ENV', 'NEW', 'Decentralized Compute Engineering', 'Distributed execution whose workload placement, environment and results are measurable and independently verifiable.', 0, 'EU / Evidence Graph only when claim scope and boundary are closed');
