INSERT INTO product_sections (product_id, section_id, primary_brick_id, build_strategy, thesis, composition_note, reuse_weight, evidence_rule) VALUES (2, 4, 'BLK-TRUST-BOUNDARY', 'ADAPT', 'Buyer: protocol / infra / AI platform / R&D lead', 'Owns a workload and a concrete trust, resilience or sovereignty constraint.', 0.5, 'EU / Evidence Graph only when claim scope and boundary are closed');
INSERT INTO product_sections (product_id, section_id, primary_brick_id, build_strategy, thesis, composition_note, reuse_weight, evidence_rule) VALUES (2, 5, 'DC-WORKLOAD-ENV', 'NEW', 'Qualification starts with centralized sufficiency', 'If ordinary cloud/Kubernetes meets the requirement, do not decentralize.', 0, 'EU / Evidence Graph only when claim scope and boundary are closed');
