INSERT INTO product_sections (product_id, section_id, primary_brick_id, build_strategy, thesis, composition_note, reuse_weight, evidence_rule) VALUES (2, 9, 'DC-EXEC-RECEIPT', 'COMPOSE', 'Workload contract, topology, execution receipt, verifier, benchmark harness, runbook', 'Artifacts remain inspectable and transferable.', 0.5, 'EU / Evidence Graph only when claim scope and boundary are closed');
