INSERT INTO product_sections (product_id, section_id, primary_brick_id, build_strategy, thesis, composition_note, reuse_weight, evidence_rule) VALUES (2, 11, 'DC-COST-PERF', 'NEW', 'Before/after on trust, reproducibility, portability, failure handling and evidence', 'Matched axes only.', 0, 'EU / Evidence Graph only when claim scope and boundary are closed');
