INSERT INTO product_sections (product_id, section_id, primary_brick_id, build_strategy, thesis, composition_note, reuse_weight, evidence_rule) VALUES (2, 14, 'DC-RESILIENCE', 'NEW', 'Bound providers, data locality, secrets, fallback and operational ownership', 'No 24/7 operations unless contracted.', 0, 'EU / Evidence Graph only when claim scope and boundary are closed');
