INSERT INTO offers (config_id, product_id, tier_id, offer_name, buyer_trigger, outcome, modules_raw, deliverables, typical_format, commercial_model, reusable_core, specific_core, entry_criteria, exit_acceptance, explicit_exclusions, evidence_contract) VALUES ('DS-O1', 1, 1, 'Research Trust & Feasibility Diagnostic', 'A claim/workflow matters, but the trust boundary is unclear', 'Decide whether decentralization or independent verification is justified', 'BLK-TRUST-BOUNDARY; DS-RESEARCH-OBJECT; DS-REVIEW-GATE', 'Trust map; claim/evidence map; architecture decision record; no-fit/next-step decision', 'Short diagnostic', 'Fixed-price', 'Mostly reused/adapted', 'DS-REVIEW-GATE', 'One consequential research claim + accessible workflow', 'Decision boundary is explicit', 'No protocol build; no legal/regulatory opinion', 'Evidence status + unsupported claims register');
INSERT INTO offers (config_id, product_id, tier_id, offer_name, buyer_trigger, outcome, modules_raw, deliverables, typical_format, commercial_model, reusable_core, specific_core, entry_criteria, exit_acceptance, explicit_exclusions, evidence_contract) VALUES ('DS-O2', 1, 2, 'Verifiable Research Protocol Architecture Sprint', 'Multiple parties need to inspect provenance, computation or attribution', 'Specify a minimum viable verifiable-research architecture', 'DS-RESEARCH-OBJECT; DS-CLAIM-GRAPH; DS-CONSENT-ACCESS; SG-THREAT-MODEL; DS-PROTOCOL-GOV', 'Protocol spec; evidence graph schema; privacy boundary; threat model; governance; PoC backlog', 'Sprint', 'Fixed-price', 'Composed from data/blockchain/security', 'DS-CLAIM-GRAPH; DS-PROTOCOL-GOV', 'Named verifier + source systems + data boundary', 'Architecture decisions + acceptance criteria signed off', 'No production operations; no scientific-validity guarantee', 'At least one admitted EU for each external factual claim');
INSERT INTO offers (config_id, product_id, tier_id, offer_name, buyer_trigger, outcome, modules_raw, deliverables, typical_format, commercial_model, reusable_core, specific_core, entry_criteria, exit_acceptance, explicit_exclusions, evidence_contract) VALUES ('DS-O3', 1, 3, 'Reproducible Evidence Pipeline PoC', 'The architecture needs one end-to-end proof', 'Demonstrate one claim path from source to independently inspectable evidence', 'DE-SOURCE-CONTRACT; DE-TRANSFORM; DE-LINEAGE; DS-REPRO-CAPSULE; DS-STUDY-ATTEST', 'Working pipeline; evidence records; reproducibility capsule; verification receipt; demo + handoff', 'Bounded PoC', 'Milestone', 'High reuse + DeSci-specific objects', 'DS-REPRO-CAPSULE; DS-STUDY-ATTEST', 'One bounded study/workflow + representative data', 'Claim path traversable + run reproducible within scope', 'No production scale or external validation', 'Acceptance artifacts stored as evidence records');
INSERT INTO offers (config_id, product_id, tier_id, offer_name, buyer_trigger, outcome, modules_raw, deliverables, typical_format, commercial_model, reusable_core, specific_core, entry_criteria, exit_acceptance, explicit_exclusions, evidence_contract) VALUES ('DS-O4', 1, 4, 'Decentralized Science Infrastructure Implementation', 'The PoC has a justified production path', 'Implement reusable research provenance, access and verification infrastructure', 'DE-DATA-MODEL; DE-EVIDENCE-STORE; DS-CONSENT-ACCESS; DS-PROTOCOL-GOV; SG-PROMOTION-GATE', 'Production-ready components; APIs; governance controls; monitoring; runbooks; handoff', '3–9 months', 'Retainer / milestones', 'Composable platform pattern', 'Domain integration / protocol adapters', 'Accepted architecture + owners + operating model', 'Release gates and ownership transferred', 'No 24/7 operation unless contracted', 'Release evidence package');
INSERT INTO offers (config_id, product_id, tier_id, offer_name, buyer_trigger, outcome, modules_raw, deliverables, typical_format, commercial_model, reusable_core, specific_core, entry_criteria, exit_acceptance, explicit_exclusions, evidence_contract) VALUES ('DS-O5', 1, 5, 'Protocol Assurance & Evidence Operations', 'An existing DeSci protocol needs evidence/architecture review', 'Test whether claimed verification properties are actually supported by the system', 'SG-THREAT-MODEL; DE-QUALITY-GATE; DS-REVIEW-GATE; DS-PROTOCOL-GOV', 'Assurance report; claim-boundary ledger; test cases; remediation backlog; re-test evidence', 'Recurring or project', 'Retainer / fixed review', 'Reuse assurance assets', 'Scientific-claim boundary review', 'Protocol/spec/code access', 'Findings tied to evidence and retestable criteria', 'Not a certification or scientific peer review', 'Every finding points to an inspectable artifact');
INSERT INTO offers (config_id, product_id, tier_id, offer_name, buyer_trigger, outcome, modules_raw, deliverables, typical_format, commercial_model, reusable_core, specific_core, entry_criteria, exit_acceptance, explicit_exclusions, evidence_contract) VALUES ('DC-O1', 2, 1, 'Workload Decentralization Diagnostic', 'A workload is proposed for decentralized execution', 'Determine whether centralization is sufficient and what property actually needs distribution or verification', 'DC-WORKLOAD-ENV; BLK-TRUST-BOUNDARY; DC-TEE-ZK-SELECT', 'Workload contract; trust map; centralized-vs-decentralized decision; benchmark plan', 'Short diagnostic', 'Fixed-price', 'Adapted blockchain qualification + new workload contract', 'DC-WORKLOAD-ENV', 'Representative workload + reason centralization is insufficient', 'Decision + benchmark metrics are explicit', 'No infrastructure build', 'No performance claim until matched benchmark');
INSERT INTO offers (config_id, product_id, tier_id, offer_name, buyer_trigger, outcome, modules_raw, deliverables, typical_format, commercial_model, reusable_core, specific_core, entry_criteria, exit_acceptance, explicit_exclusions, evidence_contract) VALUES ('DC-O2', 2, 2, 'Distributed & Verifiable Compute Architecture Sprint', 'Execution must span providers or be independently verifiable', 'Specify topology, verifier, failure model and minimum verification mechanism', 'DC-RESOURCE-TOPO; DC-VERIFY-EXEC; SG-THREAT-MODEL; DC-RESILIENCE; BLK-GOVERNANCE', 'Architecture; threat model; verifier design; failure/fallback plan; PoC backlog', 'Sprint', 'Fixed-price', 'Composed security/blockchain/data assets', 'DC-VERIFY-EXEC; DC-RESOURCE-TOPO', 'Workload envelope + trust concern + SLOs', 'Architecture decisions + failure boundaries approved', 'No universal TEE/ZK choice', 'Mechanism claims remain bounded');
